/**
 * API types, derived from the backend's OpenAPI schema (src/app/api/openapi.ts,
 * generated by `npm run api:types` from backend/openapi.yaml). Don't hand-write
 * API shapes here: when the backend changes, regenerate and let the compiler
 * point at every place that needs updating.
 */
import type { components } from '../api/openapi';

type Schemas = components['schemas'];

export type UserProfile = Schemas['UserProfile'];
export type User = Schemas['User'];
export type AuthResponse = Schemas['AuthPayload'];
export type ApiMessageResponse = Schemas['Message'];
export type ChangePasswordResponse = Schemas['ChangePasswordResponse'];
export type PasswordResetTokenResponse = Schemas['ResetTokenResponse'];
export type RegistrationCodeResponse = Schemas['SendCodeResponse'];

/** POST /auth/token/refresh/. The backend rotates refresh tokens
 *  (ROTATE_REFRESH_TOKENS), so a new `refresh` comes back too — simplejwt's
 *  serializer doesn't declare it, hence the extension. */
export type RefreshTokenResponse = Schemas['TokenRefresh'] & { refresh?: string };

export type Category = Schemas['Category'];
export type Event = Schemas['EventList'];
export type EventActionResponse = Schemas['EventStatusResult'];
export type EventStatsResponse = Schemas['EventStats'];

/**
 * A request body whose DRF DecimalFields (typed as strings in the schema) may
 * also be sent as JSON numbers, which DRF accepts. Forms bind numeric inputs.
 */
export type AcceptsNumericDecimals<T, K extends keyof T> = {
  [P in keyof T]: P extends K ? T[P] | number : T[P];
};

/** Multipart body for creating/updating an event; `image` is a File when
 *  uploading a new cover. */
export type EventFormPayload = AcceptsNumericDecimals<
  Omit<Schemas['EventCreateRequest'], 'image'>,
  'price' | 'tax_percent' | 'service_fee_percent'
> & {
  image?: File | string | null;
};

export type Registration = Schemas['Registration'];
/** A row of the organizer's attendee list (the event itself isn't repeated). */
export type EventAttendee = Schemas['AttendeeRegistration'];
export type PaymentStatus = Schemas['PaymentStatusEnum'];
export type BookingStatus = Schemas['BookingStatusEnum'];
export type CheckoutSessionResponse = Schemas['CheckoutSessionResponse'];
export type PaymentVerificationResponse = Schemas['PaymentVerification'];

export type CheckInList = Schemas['CheckInList'];
export type CheckInAttendee = Schemas['CheckInListAttendee'];
export type CheckInLogEntry = Schemas['CheckInLog'];
export type CheckInResponse = Schemas['TicketCheckInResult'];

export type Seat = Schemas['EventSeat'];
export type ZonePrice = Schemas['ZonePrice'];
export type SeatMap = Schemas['SeatMap'];

/** DRF page-number pagination envelope. */
export interface PaginatedResponse<T> {
  count: number;
  next: string | null;
  previous: string | null;
  results: T[];
}
